const robot = {
  battery: 100,
  name: "unit",
  work() {
    this.battery -= 30;
  },
};

const r1 = Object.create(robot);
const r2 = Object.create(robot);

r1.work();
r1.name = "R1";
robot.battery = 50;
r2.work();

console.log(r1.battery, r2.battery, robot.battery);
console.log(r1.name, r2.name);

delete r1.battery;
console.log(r1.battery);
